    """Replace JsonSerializer.Deserialize<TypeName>(...) with proper context version."""
    search = f'JsonSerializer.Deserialize<{type_name}>'
    result = []
    i = 0
    while i < len(content):
        idx = content.find(search, i)
        if idx == -1:
            result.append(content[i:])
            break
        result.append(content[i:idx])
        # Found the pattern, now find the opening paren
        after_search = idx + len(search)
        if after_search < len(content) and content[after_search] == '(':
            # Find matching close paren
            close = find_matching_paren(content, after_search)
            if close != -1:
                # Extract the argument(s)
                args = content[after_search+1:close]
